SELECT food_name, pantry_id FROM (
    SELECT food_name, pantry_id FROM shelfs WHERE quantity = 0
    UNION ALL
    SELECT food_name, pantry_id FROM cupboards WHERE quantity = 0
) ORDER BY food_name, pantry_id;

SELECT food_name, best_by_date FROM (
    SELECT food_name, best_by_date FROM shelfs WHERE quantity > 0 AND best_by_date < '2027-03-01'
    UNION
    SELECT food_name, best_by_date FROM cupboards WHERE quantity > 0 AND best_by_date < '2027-03-01'
) ORDER BY food_name;
